// The globe's detail, loaded when someone zooms in or goes full screen: the 50m land and borders, and the names written on the map
// (seas, countries, cities). Names are placed greedily, the most important first, and one that would touch another or a marker is left out.
// Nothing here allocates in a frame. The data is globeDetail.ts (generated by scripts/build-globe.mjs).
import { countryName } from '../../../lib/format'
import { decode, type Lines, type View } from './earth'
import { BORDERS, LAND, Q, RANK, SEAS } from './globeDetail'
import { CITIES } from './globeCities'
import { PLACES } from './globeData'

const RAD = Math.PI / 180

/** The 50m outlines and borders. */
export const fine = { land: decode(LAND, true, Q), borders: decode(BORDERS, false, Q) }

/** Names with their place as a unit vector, the text and a tier (cities and seas), in the order they are written. */
interface Names {
  xyz: Float32Array
  text: string[]
  tier: Uint8Array
  /** The width of each name at 10 px, once measured (0 before). */
  wide: Float32Array
}

function names(list: readonly (readonly [string, number, number, number])[]): Names {
  const xyz = new Float32Array(list.length * 3)
  list.forEach(([, lat, lon], i) => {
    xyz[3 * i] = Math.cos(lat * RAD) * Math.sin(lon * RAD)
    xyz[3 * i + 1] = Math.sin(lat * RAD)
    xyz[3 * i + 2] = Math.cos(lat * RAD) * Math.cos(lon * RAD)
  })
  return { xyz, text: list.map((l) => l[0]), tier: Uint8Array.from(list.map((l) => l[3])), wide: new Float32Array(list.length) }
}

const cities = names(CITIES)
const seas = names(SEAS)
// The countries, largest first, at their middle point.
const codes = RANK.split(' ').filter((cc) => PLACES[cc])
const countries = names(codes.map((cc) => [countryName(cc), PLACES[cc][0], PLACES[cc][1], 0]))

/** What the labels are drawn with (from the page's tokens). */
export interface LabelInk {
  name: string
  halo: string
  sea: string
}

/** The zoom a city of each tier is whole at. */
const FROM = [3, 3, 4, 5.5]
const MAX = 600
// The rectangles taken so far: x0, y0, x1, y1.
const taken = new Float32Array(MAX * 4)
let used = 0

/** Starts a frame's placing. */
export function clearTaken() {
  used = 0
}

/** Reserves a round area (a marker) that no name may cover. */
export function block(x: number, y: number, r: number) {
  if (used < MAX) taken.set([x - r, y - r, x + r, y + r], 4 * used++)
}

function free(x0: number, y0: number, x1: number, y1: number): boolean {
  for (let i = 0; i < used; i++) {
    const k = 4 * i
    if (x0 < taken[k + 2] && x1 > taken[k] && y0 < taken[k + 3] && y1 > taken[k + 1]) return false
  }
  return true
}

/** How visible a name is: it fades in over the stretch of zoom just before its level (so it is whole at the level), and out toward the edge of the globe. */
const fade = (zoom: number, from: number, z: number) => Math.min(1, (zoom - from + 0.4) * 2.5, (z - 0.1) * 3)

function width(c: CanvasRenderingContext2D, n: Names, i: number, size: number, tracking: number): number {
  if (!n.wide[i]) {
    c.font = '600 10px system-ui, sans-serif'
    n.wide[i] = c.measureText(n.text[i]).width + n.text[i].length * tracking * 0.1
  }
  return (n.wide[i] * size) / 10
}

/** Writes the names a view has room for. Countries from 1.5x, cities from 3x (the larger ones first), seas from the start. */
export function drawLabels(c: CanvasRenderingContext2D, v: View, zoom: number, ink: LabelInk) {
  const cl = Math.cos(v.lon * RAD)
  const sl = Math.sin(v.lon * RAD)
  const cp = Math.cos(v.lat * RAD)
  const sp = Math.sin(v.lat * RAD)
  const w = v.w ?? 1e5
  const h = v.h ?? 1e5
  c.textBaseline = 'middle'
  c.lineJoin = 'round'
  const spaced = 'letterSpacing' in c
  const at = (n: Names, i: number) => {
    const a = n.xyz
    const z1 = a[3 * i] * sl + a[3 * i + 2] * cl
    at.z = a[3 * i + 1] * sp + z1 * cp
    at.x = v.cx + v.r * (a[3 * i] * cl - a[3 * i + 2] * sl)
    at.y = v.cy - v.r * (a[3 * i + 1] * cp - z1 * sp)
  }
  at.x = at.y = at.z = 0
  // Countries: centred on their middle.
  if (zoom >= 1.1) {
    const size = Math.min(13, 10 + (zoom - 1.5) * 0.8)
    const most = 40 + zoom * 30
    c.font = `600 ${size}px system-ui, sans-serif`
    c.textAlign = 'center'
    if (spaced) (c as CanvasRenderingContext2D & { letterSpacing: string }).letterSpacing = '0.6px'
    c.lineWidth = 3
    c.strokeStyle = ink.halo
    c.fillStyle = ink.name
    for (let i = 0; i < countries.text.length && i < most; i++) {
      at(countries, i)
      if (at.z < 0.25 || at.x < 0 || at.x > w || at.y < 0 || at.y > h) continue
      const half = width(c, countries, i, size, 0.6) / 2
      if (!free(at.x - half, at.y - size * 0.6, at.x + half, at.y + size * 0.6)) continue
      // Names give way to the cities once those are many.
      c.globalAlpha = fade(zoom, 1.5, at.z) * (zoom > 5 ? Math.max(0.5, 1 - (zoom - 5) * 0.3) : 1)
      c.strokeText(countries.text[i], at.x, at.y)
      c.fillText(countries.text[i], at.x, at.y)
      taken.set([at.x - half, at.y - size * 0.6, at.x + half, at.y + size * 0.6], 4 * used++)
      if (used >= MAX) break
    }
  }
  // Cities: a dot and the name beside it.
  if (zoom >= 2.6) {
    const size = Math.min(13, 10.5 + (zoom - 3) * 0.5)
    c.font = `500 ${size}px system-ui, sans-serif`
    c.textAlign = 'left'
    if (spaced) (c as CanvasRenderingContext2D & { letterSpacing: string }).letterSpacing = '0px'
    c.lineWidth = 3
    for (let i = 0; i < cities.text.length && used < MAX - 1; i++) {
      const from = FROM[cities.tier[i]]
      if (zoom < from - 0.4) continue
      at(cities, i)
      if (at.z < 0.2 || at.x < 0 || at.x > w || at.y < 0 || at.y > h) continue
      const wide = width(c, cities, i, size, 0)
      if (!free(at.x - 4, at.y - size * 0.6, at.x + 7 + wide, at.y + size * 0.6)) continue
      c.globalAlpha = fade(zoom, from, at.z)
      c.fillStyle = ink.name
      c.beginPath()
      c.arc(at.x, at.y, 2, 0, Math.PI * 2)
      c.fill()
      c.strokeStyle = ink.halo
      c.strokeText(cities.text[i], at.x + 6, at.y)
      c.fillText(cities.text[i], at.x + 6, at.y)
      taken.set([at.x - 4, at.y - size * 0.6, at.x + 7 + wide, at.y + size * 0.6], 4 * used++)
    }
  }
  // Seas and oceans: italic, spread out, quiet. An ocean shows from the start, a sea once the view is close enough to tell it apart.
  const size = Math.min(15, 10.5 + zoom * 0.9)
  c.font = `italic 500 ${size}px system-ui, sans-serif`
  c.textAlign = 'center'
  if (spaced) (c as CanvasRenderingContext2D & { letterSpacing: string }).letterSpacing = `${(2 + zoom * 0.8).toFixed(1)}px`
  c.fillStyle = ink.sea
  for (let i = 0; i < seas.text.length && used < MAX; i++) {
    const from = seas.tier[i] === 1 ? 0.9 : 1.6
    if (zoom < from - 0.4) continue
    at(seas, i)
    if (at.z < 0.3 || at.x < 0 || at.x > w || at.y < 0 || at.y > h) continue
    const half = width(c, seas, i, size, 2 + zoom * 0.8) / 2
    if (!free(at.x - half, at.y - size * 0.6, at.x + half, at.y + size * 0.6)) continue
    // The name of a sea is reserved too, so two do not overlap, but it fades away when the zoom is far past it.
    c.globalAlpha = fade(zoom, from, at.z) * (zoom > 4.5 ? Math.max(0.35, 1 - (zoom - 4.5) * 0.3) : 1)
    c.fillText(seas.text[i], at.x, at.y)
    taken.set([at.x - half, at.y - size * 0.6, at.x + half, at.y + size * 0.6], 4 * used++)
  }
  if (spaced) (c as CanvasRenderingContext2D & { letterSpacing: string }).letterSpacing = '0px'
  c.globalAlpha = 1
}

export type Fine = { land: Lines; borders: Lines }
